(function(){
  try {
    const setValue = (customEl, val) => {
      if (!customEl) return;
      let input = customEl.shadowRoot ? customEl.shadowRoot.querySelector('input') : customEl;
      if (input) {
        input.value = val;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
      }
    };

    setValue(document.querySelector('#field-name'), 'Jane Smith');
    setValue(document.querySelector('#field-address'), '123 Test Lane');
    setValue(document.querySelector('#field-city'), 'Anytown');
    setValue(document.querySelector('#field-zip'), '00000');
    setValue(document.querySelector('#field-card'), '4111111111111111');
    setValue(document.querySelector('#field-expiry'), '12/28');
    setValue(document.querySelector('#field-cvv'), '123');

    const btn = document.querySelector('#place-order-btn');
    if (btn) {
      btn.click();
      return 'Form filled and order placed successfully';
    }
    return 'Place order button not found';
  } catch(e) {
    return 'Error: ' + e.message;
  }
})()
